function cpsQ(string $v): string { return '`'.str_replace('`','``',$v).'`'; }
function cpsAdmin(string $db=''): mysqli {
    $m=new mysqli(getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root',getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local',$db,(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306));
