    fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$out='';$err='';$until=microtime(true)+8;while(true){$out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);$st=proc_get_status($p);if(!$st['running'])break;if(microtime(true)>$until){proc_terminate($p,9);foreach([1,2]as$n)if(is_resource($pipes[$n]))fclose($pipes[$n]);proc_close($p);throw new TestFailure('SETUP_FAILURE: bounded migration runner timeout');}usleep(20000);}$out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);if($exit===-1)$exit=(int)$st['exitcode'];return compact('exit','out','err');
}
function cpsCreateExact(mysqli $db,string $p): void {$db->query('CREATE TABLE '.cpsQ($p.'fm2_migration_classification_provenance')."(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,output_kind VARCHAR(40) NOT NULL,legacy_object_id BIGINT UNSIGNED NOT NULL,output_id BIGINT UNSIGNED NOT NULL,source_cutoff_at DATETIME NOT NULL,classification_version VARCHAR(80) NOT NULL,category VARCHAR(40) NOT NULL,reason_codes_json TEXT NOT NULL,classification_sha256 CHAR(64) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY arbitrary_output_name(output_kind,output_id),KEY arbitrary_legacy_name(legacy_object_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}
