p[0]);try{cpsWaitFile($ready,2000);$env=['FMONITOR_SOURCE_HOST'=>'127.0.0.1','FMONITOR_SOURCE_PORT'=>(string)$port,'FMONITOR_SOURCE_NAME'=>'sentinel','FMONITOR_SOURCE_USER'=>'sentinel','FMONITOR_SOURCE_PASSWORD'=>'do-not-leak','FMONITOR_DB_HOST'=>getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1','FMONITOR_DB_PORT'=>(string)(getenv('FMONITOR_TEST_DB_PORT')?:23306),'FMONITOR_DB_NAME'=>$dbName,'FMONITOR_DB_USER'=>getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root','FMONITOR_DB_PASSWORD'=>getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local','FMONITOR_PILOT_ACTIVE_MANIFEST'=>$manifest];$got=cpsCli($file,$args,$env);assertSameValue([2,"{\"ok\":false,\"reason\":\"{$reason}\"}\n",''],array_values($got),"$file $mode exact public failure");assertSameValue(false,is_file($hit),"$file $mode has zero source connection");$after=['schema'=>cpsState($db,$p),'decoy'=>$db->query('SELECT * FROM '.cpsQ($p.'ambient_decoy'))->fetch_all(MYSQLI_ASSOC),'outputs'=>cpsOutputState($db,$p,$outputs),'publication'=>hash_file('sha256',$manifest),'tables'=>$db->query("SELECT TABLE_NAME,AUTO_INCREMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME LIKE '".$db->real_escape_string($p)."%' ORDER BY TABLE_NAME")->fetch_all(MYSQLI_ASSOC)];assertSameValue($before,$after,"$file $mode zero concrete output/provenance DML, ready publication, schema/counter/decoy mutation");assertSameValue(false,str_contains($got['out'].$got['err'],'sentinel')||str_contains($got['out'].$got['err'],$p),"$file diagnostics redacted");}finally{proc_terminate($server,9);foreach([1,2]as$n)if(isset($sp[$n])&&is_resource($sp[$n]))fclose($sp[$n]);proc_close($server);}}}}finally{foreach(glob($root.'/*')?:[]as$f)@unlink($f);@rmdir($root);}}
function cpsNativeContrast(mysqli$admin,mysqli$target,string$targetName,string$sourceName,string$manifest):void{$source=cpsAdmin($sourceName);try{$source->query("CREATE TABLE fm_maintable(id BIGINT PRIMARY KEY,ordadr_address VARCHAR(100),entrance VARCHAR(20),regnumber VARCHAR(40),workdatestart DATETIME,workdateendadjusted DATETIME,plan_finish_date DATETIME,workdatefinish DATETIME,ptoactdate DATETIME,responsstroicontrol BIGINT,factworkstartdate DATETIME,object_status VARCHAR(40),fact_percent INT,workstarted INT) ENGINE=InnoDB");$source->query('CREATE TABLE fm_install_checklists_values_log(value_id BIGINT,ctime DATETIME) ENGINE=InnoDB');$source->query('CREATE TABLE fm_install_checklists_values(id BIGINT PRIMARY KEY,value_id BIGINT) ENGINE=InnoDB');$source->query('CREATE TABLE fm_install_checklists_values_installators_log(checklist_value_id BIGINT,ctime DATETIME) ENGINE=InnoDB');$source->query("INSERT INTO fm_maintable VALUES(501,'Адрес','1','REG-501','2026-10-01 00:00:00','2026-10-20 00:00:00','2026-10-20 00:00:00',NULL,NULL,77,NULL,'',0,0)");$target->query("CREATE TABLE IF NOT EXISTS fm_maintable(id BIGINT PRIMARY KEY,ordadr_address VARCHAR(100),entrance VARCHAR(20),regnumber VARCHAR(40),workdatestart DATETIME,workdateendadjusted DATETIME,plan_finish_date DATETIME,workdatefinish DATETIME,ptoactdate DATETIME,responsstroicontrol BIGINT) ENGINE=InnoDB");$target->query("CREATE TRIGGER cps_conflict AFTER INSERT ON fm2_installation_cases FOR EACH ROW INSERT INTO fm2_migration_classification_provenance(output_kind,legacy_object_id,output_id,source_cutoff_at,classification_version,category,reason_codes_json,classification_sha256,created_at) VALUES('operational_case',999,NEW.id,'2026-09-02 00:00:00','injected','conflict','[]',REPEAT('f',64),'2026-09-02 00:00:01')");file_put_contents($manifest,json_encode(['processPrefix'=>'','legacyPrefix'=>''],JSON_THROW_ON_ERROR));assertSameValue([],$target->query('SELECT id FROM fm2_installation_cases WHERE legacy_installation_object_id=50