    $user='cps_'.bin2hex(random_bytes(4));$pass='p-'.bin2hex(random_bytes(8));$admin->query("CREATE USER '$user'@'%' IDENTIFIED BY '$pass'");$admin->query('GRANT SELECT,INSERT ON '.cpsQ($dbName).".* TO '$user'@'%'");
    try{$db=new mysqli(getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1',$user,$pass,$dbName,(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306));$db->set_charset('utf8mb4');$target=new MigrationClassificationProvenanceTarget($db,'');$classification=['classificationVersion'=>'pilot-v1','category'=>'eligible_native','reasonCodes'=>['OBSERVED']];foreach(['operational_case','historical_snapshot','active_baseline'] as $i=>$kind){$a=$target->reconcile($kind,100+$i,200+$i,'2026-09-02 00:00:00',$classification,'2026-09-02 01:00:00');$b=$target->reconcile($kind,100+$i,200+$i,'2026-09-02 00:00:00',$classification,'2026-09-02 01:00:00');assertSameValue([true,false],[$a['provenanceCreated'],$b['provenanceCreated']],"$kind append then replay under DDL-denied principal");try{$target->reconcile($kind,999,200+$i,'2026-09-02 00:00:00',$classification,'2026-09-02 01:00:00');throw new TestFailure("$kind conflict accepted");}catch(DomainException $e){assertSameValue('PROVENANCE_CONFLICT',$e->getMessage(),"$kind stable conflict");}}$db->close();}finally{$admin->query("DROP USER IF EXISTS '$user'@'%'");}
}
