/** @param array<int,array{0:resource,1:array<int,resource>}> $children */
function cpsReleaseAfterBothArrive(array $children,array $arrivals,string $release):void{$until=microtime(true)+8;while(true){$ready=true;foreach($arrivals as$i=>$arrival){if(!is_file($arrival)){$ready=false;$status=proc_get_status($children[$i][0]);if(!$status['running'])throw new TestFailure('injected verifier barrier is reached after each absent-v11 preflight before plain CREATE');}}if($ready)break;if(microtime(true)>$until)throw new TestFailure('injected verifier barrier reports both post-preflight arrivals before bounded release');usleep(20000);}foreach($arrivals as$i=>$arrival)assertSameValue('runner-'.($i+1),(string)file_get_contents($arrival),'exact verifier arrival token');assertSameValue(strlen('release'),file_put_contents($release,'release',LOCK_EX),'simultaneous verifier release published');}
