function cpsAbortRunner(?array $run):void{if($run===null)return;[$p,$pipes]=$run;if(is_resource($p)){$st=proc_get_status($p);if($st['running'])proc_terminate($p,9);}foreach([1,2]as$n)if(isset($pipes[$n])&&is_resource($pipes[$n]))fclose($pipes[$n]);if(is_resource($p))proc_close($p);}
function cpsDatabaseState(mysqli$db):array{$tables=$db->query("SELECT TABLE_NAME,AUTO_INCREMENT,ENGINE,TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME<>'fm2_migration_classification_provenance' ORDER BY TABLE_NAME")->fetch_all(MYSQLI_ASSOC);$out=['tables'=>$tables];foreach($tables as$t){$n=(string)$t['TABLE_NAME'];$out['rows'][$n]=$db->query('SELECT COUNT(*) n FROM '.cpsQ($n))->fetch_assoc()['n'];}return$out;}

mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);$admin=cpsAdmin();$dbName='t_cps_'.bin2hex(random_bytes(5));$aux=[];$manifest=tempnam(sys_get_temp_dir(),'cps-manifest-');
