se,\"reason\":\"SCHEMA_MIGRATION_CONFLICT\",\"schemaVersion\":11}\n",''],array_values(cpsRun($conflict,'')),"$kind drift exact conflict");assertSameValue($b,['target'=>cpsState($c,''),'decoy'=>$c->query('SELECT * FROM ambient_decoy')->fetch_all(MYSQLI_ASSOC)],"$kind drift zero mutation");$c->close();}
    $race='t_cps_race_'.bin2hex(random_bytes(4));$aux[]=$race;$admin->query('CREATE DATABASE '.cpsQ($race).' DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci');assertSameValue(0,cpsRun($race,'')['exit'],'race predecessor setup');$raceDb=cpsAdmin($race);$raceDb->query('DROP TABLE fm2_migration_classification_provenance');$raceDb->query("INSERT INTO fm2_installation_cases(id,legacy_installation_object_id,process_state,actual_start_date,opened_at,opened_by_user_id,created_at,updated_at,lock_version) VALUES(77,707,'requires_order',NULL,NULL,NULL,'created','updated',3)");$raceDb->query('ALTER TABLE fm2_installation_cases AUTO_INCREMENT=90');$raceDb->query('CREATE TABLE race_decoy(id INT PRIMARY KEY,value VARCHAR(20))');$raceDb->query("INSERT INTO race_decoy VALUES(1,'populated')");$raceBefore=cpsDatabaseState($raceDb);$barrierRoot=sys_get_temp_dir().'/cps-barrier-'.bin2hex(random_bytes(5));if(!mkdir($barrierRoot,0700,true))throw new TestFailure('SETUP_FAILURE: verifier barrier root');$arrivals=[$barrierRoot.'/arrival-1',$barrierRoot.'/arrival-2'];$release=$barrierRoot.'/release';$children=[];try{$children[]=cpsStartRunner($race,$arrivals[0],$release,'runner-1');$children[]=cpsStartRunner($race,$arrivals[1],$release,'runner-2');cpsReleaseAfterBothArrive($children,$arrivals,$release);$results=[];foreach(array_keys($children)as$k){$results[]=cpsFinishRunner($children[$k]);$children[$k]=null;}}finally{foreach($children as$child)cpsAbortRunner($child);foreach([$arrivals[0],$arrivals[1],$release]as$file)if(is_file($file))unlink($file);rmdir($barrierRoot);}sort($results);assertSameValue([[0,"{\"ok\":true,\"schemaVersion\":11,\"appliedVersions\":[11]}\n",''],[70,"{\"ok\":false,\"reason\":\"MIGRATION_FAILED\"}\n",'']],$results,'bounded two verifier-composed real-runner winner/loser outcome');assertSameValue($raceBefore,cpsDatabaseState($raceDb),'populated v1-v10 predecessor rows/counter and decoy unchanged');cpsAssertManifest($raceDb,'');cpsAssertIndexes($raceDb,'');assertSameValue([],cpsState($raceDb,'')['rows'],'race final target exact empty');assertSameValue([0,"{\"ok\":true,\"schemaVersion\":11,\"appliedVersions\":[]}\n",''],array_values(cpsRun($race,'')),'ordinary production repeat after verifier race');$raceDb->close();
    cpsRuntimeNoDdl($admin,$dbName);cpsRuntimeCliBoundaries($db,$dbName,$manifest);$sourceName='t_cps_source_'.bin2hex(random_bytes(4));$aux[]=$sourceName;$admin->query('CREATE DATABASE '.cpsQ($sourceName).' DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci');cpsNativeContrast($admin,$db,$dbName,$sourceName,$manifest);cpsRuntimeDdlRatchet();
